# JsonUtility

Serialize public primitive fields and Vector2/Vector3 with ToJson, FromJson<T> and FromJsonOverwrite. Compiled generic type roots preserve public fields for AOT. Nested classes, lists, polymorphism, dictionaries and private serialized fields are not supported and throw. Use PlayerPrefs.SetString/Save to persist the returned JSON. Example: var json = JsonUtility.ToJson(new SaveData()); var data = JsonUtility.FromJson<SaveData>(json);


## Implemented declarations

```csharp
public static class JsonUtility {
 // Explicit public-field serializer. Reflection roots are preserved for compiled script classes.
 public static string ToJson<[System.Diagnostics.CodeAnalysis.DynamicallyAccessedMembers(System.Diagnostics.CodeAnalysis.DynamicallyAccessedMemberTypes.PublicFields)]T>(T value,bool prettyPrint=false){using var stream=new MemoryStream();using(var writer=new Utf8JsonWriter(stream,new JsonWriterOptions{Indented=prettyPrint})){writer.WriteStartObject();foreach(var f in typeof(T).GetFields(System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.Public)){writer.WritePropertyName(f.Name);Write(writer,f.GetValue(value));}writer.WriteEndObject();}return System.Text.Encoding.UTF8.GetString(stream.ToArray());}
 private static void Write(Utf8JsonWriter w,object? v){switch(v){case null:w.WriteNullValue();break;case string s:w.WriteStringValue(s);break;case bool b:w.WriteBooleanValue(b);break;case int n:w.WriteNumberValue(n);break;case double n:w.WriteNumberValue(n);break;case float n:w.WriteNumberValue(n);break;case long n:w.WriteNumberValue(n);break;case Vector2 p:w.WriteStartObject();w.WriteNumber("x",p.X);w.WriteNumber("y",p.Y);w.WriteEndObject();break;case Vector3 p:w.WriteStartObject();w.WriteNumber("x",p.X);w.WriteNumber("y",p.Y);w.WriteNumber("z",p.Z);w.WriteEndObject();break;default:throw new NotSupportedException("JsonUtility supports primitive public fields and Vector2/Vector3; unsupported value "+v.GetType().Name);}}
 public static T FromJson<[System.Diagnostics.CodeAnalysis.DynamicallyAccessedMembers(System.Diagnostics.CodeAnalysis.DynamicallyAccessedMemberTypes.PublicFields|System.Diagnostics.CodeAnalysis.DynamicallyAccessedMemberTypes.PublicParameterlessConstructor)]T>(string json) where T:new(){var value=new T();return ReadFields(json,value);}
 public static void FromJsonOverwrite<[System.Diagnostics.CodeAnalysis.DynamicallyAccessedMembers(System.Diagnostics.CodeAnalysis.DynamicallyAccessedMemberTypes.PublicFields)]T>(string json,T target){if(typeof(T).IsValueType)throw new ArgumentException("Use FromJson<T> or the ref overload for value types");_=ReadFields(json,target);}
 public static void FromJsonOverwrite<[System.Diagnostics.CodeAnalysis.DynamicallyAccessedMembers(System.Diagnostics.CodeAnalysis.DynamicallyAccessedMemberTypes.PublicFields)]T>(string json,ref T target)=>target=ReadFields(json,target);
 private static T ReadFields<[System.Diagnostics.CodeAnalysis.DynamicallyAccessedMembers(System.Diagnostics.CodeAnalysis.DynamicallyAccessedMemberTypes.PublicFields)]T>(string json,T target){object boxed=target??throw new ArgumentNullException(nameof(target));using var doc=JsonDocument.Parse(json);foreach(var f in typeof(T).GetFields(System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.Public)){if(f.IsInitOnly||!doc.RootElement.TryGetProperty(f.Name,out var v))continue;object? parsed=f.FieldType==typeof(string)?v.GetString():f.FieldType==typeof(bool)?v.GetBoolean():f.FieldType==typeof(int)?v.GetInt32():f.FieldType==typeof(double)?v.GetDouble():f.FieldType==typeof(float)?v.GetSingle():f.FieldType==typeof(long)?v.GetInt64():f.FieldType==typeof(Vector2)?new Vector2(v.GetProperty("x").GetDouble(),v.GetProperty("y").GetDouble()):f.FieldType==typeof(Vector3)?new Vector3(v.GetProperty("x").GetDouble(),v.GetProperty("y").GetDouble(),v.GetProperty("z").GetDouble()):throw new NotSupportedException("Unsupported JSON field "+f.Name);f.SetValue(boxed,parsed);}return (T)boxed;}
